class Solution {
public:
    string mostCommonWord(string paragraph, vector<string>& banned) {
        unordered_set<string> ban(banned.begin(), banned.end());
        unordered_map<string, int> count;
        int n = (int)paragraph.size();
        int i = 0;
        string best;
        int bestCount = 0;
        while (i < n) {
            while (i < n && !isLetter(paragraph[i])) i++;
            if (i >= n) break;
            string word;
            while (i < n && isLetter(paragraph[i])) {
                char c = paragraph[i];
                if (c >= 'A' && c <= 'Z') c = c - 'A' + 'a';
                word += c;
                i++;
            }
            if (ban.find(word) == ban.end()) {
                count[word]++;
                if (count[word] > bestCount) {
                    bestCount = count[word];
                    best = word;
                }
            }
        }
        return best;
    }
private:
    static bool isLetter(char c) {
        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
    }
};
